#!/usr/bin/env node
// Generates docs/REPO-MAP.md -- a ~1k-token orientation map (routes, models,
// lib exports, shared components) so sessions get O(1) orientation instead of
// O(files) exploratory reads (ADR-019; aider repo-map pattern, sized down).
// Regenerated by the SessionStart hook when schema/app/lib are newer than the map.
import { readFileSync, writeFileSync, readdirSync, existsSync } from "node:fs";
import { join, relative } from "node:path";

const root = process.cwd();
const out = ["# Repo map (generated -- do not edit; `node scripts/repo-map.mjs`)", ""];
// Precompiled once (not per route file): method -> its export-detector regex.
const HTTP_METHOD_RES = "GET POST PUT PATCH DELETE"
  .split(" ")
  .map((m) => [m, new RegExp(`export const ${m}\\b`)]);

function walk(dir, fn) {
  for (const e of readdirSync(dir, { withFileTypes: true })) {
    const p = join(dir, e.name);
    if (e.isDirectory()) walk(p, fn);
    else fn(p);
  }
}

// API routes + pages
out.push("## Routes (app/)");
const routes = [];
walk(join(root, "app"), (p) => {
  const rel = relative(root, p);
  if (/\/(route|page)\.tsx?$/.test(rel)) {
    let methods = "";
    if (rel.endsWith("route.ts")) {
      const src = readFileSync(p, "utf8");
      methods = HTTP_METHOD_RES.filter(([, re]) => re.test(src))
        .map(([m]) => m)
        .join(",");
    }
    routes.push(`- ${rel}${methods ? `  [${methods}]` : ""}`);
  }
});
out.push(...routes.sort(), "");

// Prisma models
out.push("## Models (prisma/schema.prisma)");
const schema = readFileSync(join(root, "prisma/schema.prisma"), "utf8");
for (const m of schema.matchAll(/^model (\w+) \{([^}]*)\}/gms)) {
  const fields = [...m[2].matchAll(/^\s{2}(\w+)\s+(\S+)/gm)]
    .map((f) => f[1])
    .filter((f) => !f.startsWith("@@"));
  out.push(`- ${m[1]}: ${fields.join(", ")}`);
}
out.push("");

// lib exports
out.push("## lib/ exports");
walk(join(root, "lib"), (p) => {
  if (!p.endsWith(".ts")) return;
  const names = [
    ...readFileSync(p, "utf8").matchAll(
      /^export (?:async )?(?:function|const|class|type|interface) (\w+)/gm,
    ),
  ].map((m) => m[1]);
  if (names.length) out.push(`- ${relative(root, p)}: ${names.join(", ")}`);
});
out.push("");

// shared components
out.push("## components/");
walk(join(root, "components"), (p) => {
  if (p.endsWith(".tsx")) out.push(`- ${relative(root, p)}`);
});

const target = join(root, "docs/REPO-MAP.md");
const rendered = out.join("\n") + "\n";

// `--check` compares instead of writing, so /ship can gate on drift (2026-08-21).
// The map went stale TWICE in two days -- once when the dormant-layer cut removed
// components, once when three lib/ exports were made module-private -- and both times
// the only signal was an uncommitted modification at SessionStart, which reads as noise.
// Two of those stale entries advertised symbols that had been deliberately un-exported,
// so the index was actively arguing against the change that had just been made.
if (process.argv.includes("--check")) {
  const current = existsSync(target) ? readFileSync(target, "utf8") : "";
  if (current === rendered) {
    console.log("repo-map: up to date");
    process.exit(0);
  }
  const a = current.split("\n");
  const b = rendered.split("\n");
  const removed = a.filter((l) => l.trim() && !b.includes(l));
  const added = b.filter((l) => l.trim() && !a.includes(l));
  console.error("docs/REPO-MAP.md is STALE -- it does not match the current tree.");
  for (const l of removed.slice(0, 10)) console.error(`  - ${l}`);
  for (const l of added.slice(0, 10)) console.error(`  + ${l}`);
  const extra =
    removed.length + added.length - Math.min(removed.length, 10) - Math.min(added.length, 10);
  if (extra > 0) console.error(`  ... and ${extra} more line(s)`);
  console.error("  Fix: npm run repo-map   (then commit the result)");
  process.exit(1);
}

writeFileSync(target, rendered);
console.log(`repo-map: ${out.length} lines -> docs/REPO-MAP.md`);
